var zonePolicies = map[string]struct {
	rate      int
	surcharge int
}{
	"domestic": {rate: 499, surcharge: 10},
	"regional": {rate: 899, surcharge: 15},
	"overseas": {rate: 1899, surcharge: 25},
}

func Rate(zone string) (int, error) {
	policy, ok := zonePolicies[zone]
	if !ok {
		return 0, fmt.Errorf("rate %q: unknown zone", zone)
